    public static VendInvoiceWorkflow newVendInvoiceWorkflow(Args _args)
    {
        VendInvoiceWorkflow     vendInvoiceWorkflow = next newVendInvoiceWorkflow(_args);
        WorkflowWorkItemTable   workItem;
        VendInvoiceInfoTable    vendInvoiceInfoTable;
        str                     callerMenuItem;

        if (_args && _args.caller())
        {
            callerMenuItem = _args.menuItemName();
            workItem = _args.caller().getActiveWorkflowWorkItem();
        }

        if (workItem)
        {
            vendInvoiceInfoTable = workItem.getRecord();
        }
        else
        {
            vendInvoiceInfoTable = _args.record();
        }

        if(callerMenuItem == menuitemActionStr(VendInvoiceHeaderWorkflowSubmit))
        {
            vendInvoiceInfoTable.ImportedAmount = 0;
            vendInvoiceInfoTable.ImportedSalesTax = 0;

            _args.record(vendInvoiceInfoTable);
        }

        return vendInvoiceWorkflow;
    }
